package com.sathavahana.kalamkari.service;
import com.sathavahana.kalamkari.domain.*; import com.sathavahana.kalamkari.dto.OrderDto; import com.sathavahana.kalamkari.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*;
@Service public class OrderService {private final OrderRepository orders; private final CartRepository carts; private final ProductRepository products; private final CurrentUser current; private final PaymentService payments; public OrderService(OrderRepository o,CartRepository c,ProductRepository p,CurrentUser u,PaymentService ps){orders=o;carts=c;products=p;current=u;payments=ps;} public record Checkout(String paymentMethod,String idempotencyKey){} @Transactional public OrderDto checkout(Checkout request){var u=current.require(); var c=carts.findByUserId(u.getId()).orElseThrow(()->new IllegalArgumentException("Cart is empty")); if(c.getItems().isEmpty())throw new IllegalArgumentException("Cart is empty"); var o=new Order(u);var total=BigDecimal.ZERO;for(var item:c.getItems()){var p=products.findLocked(item.getProduct().getId()).orElseThrow();if(!p.isActive()||p.getStockQuantity()<item.getQuantity())throw new IllegalArgumentException("Insufficient stock for "+p.getName());p.setStockQuantity(p.getStockQuantity()-item.getQuantity());var oi=new OrderItem(o,p,item.getQuantity());o.getItems().add(oi);total=total.add(p.getPrice().multiply(BigDecimal.valueOf(item.getQuantity())));}o.setTotalAmount(total.add(shipping(total)));var saved=orders.save(o);payments.pay(saved,request==null?"COD":request.paymentMethod(),request==null?"legacy-"+saved.getId():request.idempotencyKey());c.getItems().clear();carts.save(c);return OrderDto.of(saved);} private BigDecimal shipping(BigDecimal subtotal){return subtotal.compareTo(BigDecimal.valueOf(2500))>=0?BigDecimal.ZERO:BigDecimal.valueOf(99);} @Transactional public OrderDto checkout(){return checkout(new Checkout("COD","legacy-"+java.util.UUID.randomUUID()));} @Transactional(readOnly=true) public java.util.List<OrderDto> list(){return orders.findByUserIdOrderByCreatedAtDesc(current.require().getId()).stream().map(OrderDto::of).toList();}}
